import{_ as t,o,c as d,a2 as s}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Host Services","description":"","frontmatter":{},"headers":[],"relativePath":"dev-guide/sdk/services.md","filePath":"dev-guide/sdk/services.md","lastUpdated":1783414071000}'),r={name:"dev-guide/sdk/services.md"};function i(a,e,c,n,l,h){return o(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="host-services" tabindex="-1">Host Services <a class="header-anchor" href="#host-services" aria-label="Permalink to &quot;Host Services&quot;">​</a></h1><p>Static services in <code>PluginSdk.Services</code> that expose host-app functionality back to plugins — each is a thin static class wrapping a delegate the host wires up at startup, so plugins call them the same way regardless of what&#39;s running underneath.</p><table tabindex="0"><thead><tr><th>Service</th><th>Purpose</th></tr></thead><tbody><tr><td><code>TranslationService</code></td><td><code>Get(key)</code> / <code>Format(key, args)</code> for runtime lookups against the active language; <code>LoadEmbeddedTranslations(assembly, cultureKey, typeName)</code> to load a plugin&#39;s own embedded JSON translations; <code>GetSupportedCultures(assembly)</code>.</td></tr><tr><td><code>IconService</code></td><td><code>GetIcon(path, isDir)</code> and <code>GetThumbnail(path, size)</code> — cached shell icon/thumbnail extraction, so a plugin never has to shell out to the Windows icon APIs itself.</td></tr><tr><td><code>FavoritesService</code></td><td><code>GetFavorites()</code> — read-only access to the user&#39;s <a href="./../../user-guide/settings/favorites.html">Favorites</a> list (<code>FavoriteItem</code>: Name, Path).</td></tr><tr><td><code>HistoryService</code></td><td><code>GetHistoryPaths()</code> — recently-visited paths from <a href="./../../user-guide/settings/history.html">History</a>.</td></tr><tr><td><code>FileMetadataService</code></td><td><code>GetMetadataAsync(paths)</code> — batched Size/Created/Modified/Accessed lookup (<code>FileMetadata</code> record struct), for plugins adding a <a href="./ui-extensions.html#iresultcolumnprovider">result column</a> that needs this data for many results at once.</td></tr><tr><td><code>DirectoryIndexerService</code></td><td><code>RegisterDirectory(pluginId, path, recursive, filterPattern)</code> / <code>UnregisterDirectories(pluginId)</code> / <code>SearchDirectoriesAsync(pluginId, query, token)</code> / <code>NotifyDirectoryChanged(pluginId)</code> — lets a plugin register its own directories for background indexing and USN monitoring without reimplementing that machinery.</td></tr><tr><td><code>PluginSettingsService</code></td><td><code>GetSetting&lt;T&gt;(pluginId, key, defaultValue)</code> — read-only access to a plugin&#39;s own persisted settings from the host&#39;s config store.</td></tr><tr><td><code>Logger</code></td><td><code>Log(message, level = LogLevel.Info)</code> — writes to the App&#39;s log file, visible in <strong>Settings → Service Status → App</strong> exactly like the host&#39;s own log lines.</td></tr></tbody></table><p><code>LogLevel</code> is <code>Error</code> / <code>Warn</code> / <code>Info</code> / <code>Debug</code>, matching the level filter in the <a href="./../../user-guide/settings/service-status.html">Service Status log viewer</a>.</p>',4)])])}const p=t(r,[["render",i]]);export{g as __pageData,p as default};
